DO $$
DECLARE
  v_user_id uuid;
  v_project_id uuid;
  v_form_id uuid;
  v_widget_id uuid;
BEGIN
  SELECT id INTO v_user_id FROM auth.users WHERE email = 'sritrvler@gmail.com' LIMIT 1;
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'User not found. Check the email address.';
  END IF;

  INSERT INTO public.projects (id, user_id, name, slug, website, accent_color, form_bg_color, text_color, input_color) VALUES (uuid_generate_v4(), v_user_id, 'Vouch', 'vouch', 'https://vouch-xa3m.vercel.app', '#6366F1', '#ffffff', '#1a1a1a', '#ffffff') RETURNING id INTO v_project_id;

  INSERT INTO public.collection_forms (id, project_id, user_id, title, description, prompt, custom_questions, is_active) VALUES (uuid_generate_v4(), v_project_id, v_user_id, 'Share your Vouch experience', 'Your feedback helps other founders and agencies discover Vouch. Takes under 2 minutes.', 'What was collecting testimonials like before Vouch, and how is it different now?', ARRAY['What specific results have you seen? (e.g., more conversions, time saved, client satisfaction)', 'What is your favorite feature and why?'], true) RETURNING id INTO v_form_id;

  INSERT INTO public.widgets (id, project_id, user_id, name, layout, theme, filter_mode, max_items) VALUES (uuid_generate_v4(), v_project_id, v_user_id, 'Homepage Wall', 'wall', '{"primaryColor":"#6366F1","backgroundColor":"#ffffff","textColor":"#0f172a","cardStyle":"shadow","fontFamily":"inherit","fontUrl":null,"showRating":true,"showAvatar":true,"showDate":true,"showSource":false}', 'all', 12) RETURNING id INTO v_widget_id;

  INSERT INTO public.widgets (project_id, user_id, name, layout, theme, filter_mode, max_items) VALUES (v_project_id, v_user_id, 'Pricing Page Carousel', 'carousel', '{"primaryColor":"#6366F1","backgroundColor":"#ffffff","textColor":"#0f172a","cardStyle":"shadow","fontFamily":"inherit","fontUrl":null,"showRating":true,"showAvatar":true,"showDate":false,"showSource":false}', 'featured', 6);

  INSERT INTO public.testimonials (project_id, user_id, form_id, author_name, author_email, author_role, author_company, rating, content, status, source, featured, custom_answers, created_at) VALUES (v_project_id, v_user_id, v_form_id, 'Priya Sharma', 'priya@novadigital.in', 'CEO', 'Nova Digital', 5, 'Before Vouch, we were screenshotting Slack messages and LinkedIn DMs to use as testimonials. It looked unprofessional and took hours to format. Now each of our 12 clients has their own project with a branded collection form. We send it after every deliverable and the testimonials just flow in. The client reports feature alone justified the upgrade to Studio.', 'approved', 'form', true, '{"What specific results have you seen?":"Our clients love the reports. Two of them started using Vouch for their own businesses after seeing ours.","What is your favorite feature and why?":"Multi-project management. Managing testimonials across 12 clients in one dashboard saves us hours every week."}', now() - interval '21 days');

  INSERT INTO public.testimonials (project_id, user_id, form_id, author_name, author_email, author_role, author_company, rating, content, status, source, featured, custom_answers, created_at) VALUES (v_project_id, v_user_id, v_form_id, 'Tom Nguyen', 'tom@shipfast.dev', 'Founder', 'ShipFast', 5, 'Launched my SaaS last month and needed social proof fast. Set up Vouch in 15 minutes, sent the collection form to my beta users, and had a testimonials wall on my landing page the same day. Went from zero social proof to 14 testimonials in a week. The embed widget matched my brand perfectly without any custom CSS.', 'approved', 'form', true, '{"What specific results have you seen?":"Pricing page conversion went from 2.1% to 3.4% after adding the testimonial carousel. That is real money.","What is your favorite feature and why?":"The wall layout. It fills the page with social proof and looks like I built it custom."}', now() - interval '18 days');

  INSERT INTO public.testimonials (project_id, user_id, form_id, author_name, author_email, author_role, author_company, rating, content, status, source, featured, custom_answers, created_at) VALUES (v_project_id, v_user_id, v_form_id, 'Marcus Rivera', 'marcus@studioflow.co', 'Freelance Designer', 'StudioFlow', 5, 'Social proof was always an afterthought for me. I would finish a project, forget to ask for a testimonial, and end up with nothing to show. Vouch changed that completely. I send clients the form link in my offboarding email, and they actually fill it out because it looks clean and takes 2 minutes. My portfolio site went from zero testimonials to eight in the first month.', 'approved', 'form', false, '{"What specific results have you seen?":"I have closed 3 new clients who specifically mentioned the testimonials on my site during our intro call.","What is your favorite feature and why?":"Video testimonials. One client recorded a 45 second video and it is the most convincing thing on my entire website."}', now() - interval '14 days');

  INSERT INTO public.testimonials (project_id, user_id, form_id, author_name, author_email, author_role, author_company, rating, content, status, source, featured, custom_answers, created_at) VALUES (v_project_id, v_user_id, v_form_id, 'Elena Vasquez', 'elena@craftandcode.com', 'Founder', 'Craft & Code', 5, 'I was paying $49/month for a competitor that did half of what Vouch does. The free plan here gave me enough to test everything properly. Once I saw how clean the widgets looked and how easy the collection flow was, upgrading to Pro was obvious. Saved $30/month and got a better product.', 'approved', 'form', true, '{"What specific results have you seen?":"Saved $360/year switching from my old tool. The embed loads faster too, which probably helps with SEO.","What is your favorite feature and why?":"The collection form. My old tool had an ugly form that clients complained about. This one actually looks like it belongs to my brand."}', now() - interval '10 days');

  INSERT INTO public.testimonials (project_id, user_id, form_id, author_name, author_email, author_role, author_company, rating, content, status, source, featured, custom_answers, created_at) VALUES (v_project_id, v_user_id, v_form_id, 'Sarah Chen', 'sarah@linearteam.io', 'Head of Marketing', 'Linear', 5, 'We needed a testimonial solution that did not look like a third party widget. Vouch nailed that. The embeds blend seamlessly with our site, the fonts match, the colors match. Our design team approved it on the first review, which never happens with third party tools. Collecting testimonials from customers is now part of our post-onboarding flow.', 'approved', 'form', true, '{"What specific results have you seen?":"22% increase in demo requests on the page where we added the testimonial wall. The design team actually wants to add more.","What is your favorite feature and why?":"Custom fonts on the widget. Small detail but it makes all the difference for brand consistency."}', now() - interval '8 days');

  INSERT INTO public.testimonials (project_id, user_id, form_id, author_name, author_email, author_role, author_company, rating, content, status, source, featured, custom_answers, created_at) VALUES (v_project_id, v_user_id, v_form_id, 'James Whitfield', 'james@pipelinecrm.io', 'CTO', 'PipelineCRM', 4, 'From a technical perspective, Vouch does things right. The embed script is lightweight, uses Shadow DOM so it does not conflict with our styles, and the API responses are fast. I was skeptical about adding another third party script to our marketing site but the performance impact is negligible. One less thing to worry about.', 'approved', 'form', false, '{"What specific results have you seen?":"The embed loads in under 200ms on our site. No layout shift, no flash of unstyled content. Our Lighthouse scores stayed the same.","What is your favorite feature and why?":"Shadow DOM isolation. Our CSS is complex and every other widget we tried broke something. Vouch just works."}', now() - interval '5 days');

  INSERT INTO public.testimonials (project_id, user_id, form_id, author_name, author_email, author_role, author_company, rating, content, status, source, featured, custom_answers, created_at) VALUES (v_project_id, v_user_id, v_form_id, 'Aisha Okonkwo', 'aisha@brightstudio.co', 'Creative Director', 'Bright Studio', 5, 'What sold me on Vouch is that the widgets genuinely look like something I built. My clients cannot tell it is a third party tool, and that is exactly what I wanted. The collection form is beautiful too. I have gotten compliments from customers on the form itself, which says a lot.', 'approved', 'form', false, '{"What specific results have you seen?":"Response rate on the collection form is around 60%, way higher than the email approach I was using before.","What is your favorite feature and why?":"The branded collection form. It matches my site perfectly and customers enjoy filling it out."}', now() - interval '2 days');

  INSERT INTO public.testimonials (project_id, user_id, form_id, author_name, author_email, author_role, author_company, rating, content, status, source, featured, custom_answers, created_at) VALUES (v_project_id, v_user_id, v_form_id, 'Daniel Park', 'daniel@launchpad.so', 'Product Manager', 'Launchpad', 5, 'Just started using Vouch this week after seeing it on a friend''s website. The setup took maybe 10 minutes. Already collected 3 testimonials from customers and the grid widget on our landing page looks fantastic. Genuinely surprised this is not more well known yet.', 'pending', 'form', false, '{"What specific results have you seen?":"Too early for conversion data but the qualitative feedback from our team has been great. Everyone loves how it looks.","What is your favorite feature and why?":"How fast it was to set up. I expected at least an hour of configuration. It took 10 minutes."}', now() - interval '3 hours');

  RAISE NOTICE 'Done! Project: %, Form: %, Wall widget: %, 8 testimonials inserted.', v_project_id, v_form_id, v_widget_id;
END $$;
